  "status": "SUPPORTED",
  "claim": {
    "component_id": "C008",
    "value": "Repeated tests of candidate earlier and later revisions under matched conditions are proposed as the means of establishing good and bad endpoints.",
    "scope": "Initial endpoint-establishment procedure; success is not guaranteed.",
    "provenance": {
      "refs": [
        {
          "source_id": "P007",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "The span supplies the proposed operation, matching requirement and purpose."
    }
  },
  "signal_basis": {
    "component_id": "C008_SIGNAL",
    "value": "Repeated matched trials of candidate endpoint revisions yield export counts, fractions exceeding one hour and uncertainty. Prespecified evidence rules classify each revision as good, bad or inconclusive, with adequate replication and control of repeated-testing error.",
    "scope": "Endpoint classification under matched tested conditions; a small sample without slow exports does not establish goodness.",
    "provenance": {
      "refs": [
